-- 🛒 SELL: load the Cimac products we sell -- the Include list PLUS the pro range, punch bags, pro body
-- protectors, Muay Thai T-shirts and the accessories item (Judo, Karate, TKD, BJJ, Kung fu left out).
-- Selling price = Cimac retail, cost = Cimac trade ex VAT, supplier Cimac, every size / colour as an option,
-- stock starting at 0. Anything already in Sell with the same name is skipped, so it's safe to run even if
-- the first file was already run.
alter table public.stock_items add column if not exists supplier text;
create temp table if not exists kc_cimac (name text, category text, cost numeric, price numeric, sizes text);
truncate kc_cimac;

with ins as (
  select c.name, c.category, 'Cimac', c.cost, c.price, 0, true from kc_cimac c
  where not exists (select 1 from stock_items s where lower(s.name) = lower(c.name))
  returning id, name
)
select ins.id, v.label, 0, v.ord
from ins join kc_cimac c on c.name = ins.name
cross join lateral unnest(string_to_array(c.sizes, '|')) with ordinality as v(label, ord);

select category, count(*) as items from stock_items where supplier = 'Cimac' group by category order by category;
